+// ConnectionURL resolves the active database settings into a driver URL.
+// A configured URL always takes precedence over individual settings.
+func (d DatabaseConfig) ConnectionURL() (string, error) {
+	if d.URL != "" {
+		return d.URL, nil
+	}
+	if d.Protocol.String() == "" {
+		return "", fmt.Errorf("db.protocol: invalid value %d (expected sqlite3, postgres, or mysql)", d.Protocol)
+	}
+	if d.Name == "" {
+		return "", errors.New("db.name: cannot be empty")
+	}
+	if d.Port < 0 || d.Port > 65535 {
+		return "", fmt.Errorf("db.port: invalid value %d (expected 1-65535 or 0 for the default)", d.Port)
+	}
+
+	if d.Protocol == SQLite {
+		path := d.Path
+		if path == "" {
+			path = d.Host
+		}
+		if path == "" {
+			return "", errors.New("db.host or db.path: cannot be empty for sqlite3")
+		}
+		if d.Port != 0 {
+			return "", errors.New("db.port: not supported for sqlite3")
+		}
+		return (&url.URL{Scheme: "file", Path: filepath.Join(path, d.Name)}).String(), nil
+	}
+	if d.Host == "" {
+		return "", errors.New("db.host: cannot be empty")
+	}
+	port := d.Port
+	if port == 0 {
+		if d.Protocol == Postgres {
+			port = 5432
+		} else {
+			port = 3306
+		}
+	}
